installer-gui-script.script:
// coreaudiod loads the HAL plugin in the native architecture: the package must match the Mac.
function matchesMac() {
    var appleSilicon = system.sysctl('hw.optional.arm64') == 1;
    if (appleSilicon == __APPLE_SILICON__) {
        return true;
    }
    my.result.type = 'Fatal';
    my.result.title = 'This package does not match this Mac';
    my.result.message = appleSilicon
        ? 'This Mac has an Apple Silicon chip. Download the OpenLW package for Apple Silicon (arm64).'
        : 'This Mac has an Intel processor. Download the OpenLW package for Intel (x86_64).';
    return false;
}
